/* Reviewed data packs and account-scoped backup. All AI use is manual and optional. */
(function(){'use strict';const A=DecideContentAuthoring,E=EvervaleEditor,S=EvervaleContentSchema,el=id=>document.getElementById(id),copy=x=>JSON.parse(JSON.stringify(x));let pending=null;const panel=document.createElement('article');panel.id='dataAuthoring';panel.innerHTML=`<h2>เพิ่มข้อมูลที่ใช้ได้จริง / ส่งให้ AI ฟรีช่วยกรอก</h2><p>เลือกแม่แบบกลไกที่รองรับ แล้วเพิ่มชื่อและตัวเลขได้โดยไม่แก้โค้ด คำบรรยายไม่เพิ่มกลไกใหม่</p><label>แม่แบบ<select id="authorTemplate"></select></label><p id="authorMechanic" class="muted"></p><label>ชื่ออ้างอิงรายการใหม่<input id="authorName" maxlength="120" placeholder="เช่น ศรอัคคีฝึกหัด"></label><button id="authorCreate">สร้างจากแม่แบบแล้วแก้ข้อมูล</button><details><summary>ใช้ ChatGPT / Claude ฟรีช่วยกรอกข้อมูล</summary><p>ดาวน์โหลดคำสั่งและแม่แบบ เปิดไฟล์แล้วคัดลอกไปวางในแชต AI จากนั้นนำ JSON คำตอบกลับมาตรวจ ไม่มีการเชื่อมบัญชี AI หรือใช้ API</p><label>สิ่งที่ต้องการให้ AI ช่วย<textarea id="authorTask" rows="3" placeholder="เช่น สร้างเวทไฟ 3 ระดับ ใช้กลไกโจมตีจากแม่แบบนี้"></textarea></label><button id="authorRequest">ดาวน์โหลดคำสั่งพร้อมแม่แบบให้ AI</button><label>วาง JSON คำตอบ<textarea id="authorPack" rows="8" spellcheck="false"></textarea></label><label>หรือเลือกไฟล์คำตอบ JSON<input id="authorFile" type="file" accept=".json,application/json"></label><button id="authorPreview">ตรวจและดูสิ่งที่จะเปลี่ยน</button></details><div id="authorReview" hidden><h3>ตรวจรายการก่อนบันทึก</h3><div id="authorChanges"></div><p>เป็นการรวมข้อมูล ไม่ล้างรายการอื่น ระบบจะสำรองฐานข้อมูลเดิมก่อนบันทึก เซฟตัวละครไม่เปลี่ยน</p><button id="authorApply" class="primary">ยืนยันบันทึกชุดนี้</button><button id="authorCancel">ยกเลิกชุดที่ตรวจไว้</button></div><details><summary>สำรอง / ย้อนคืนข้อมูล</summary><p>สำรองล่าสุดเก็บแยกตามบัญชีในเบราว์เซอร์นี้ ควรส่งออกไฟล์เต็มชุดก่อนเปลี่ยนเครื่องหรือเคลียร์ข้อมูลเบราว์เซอร์</p><button id="authorRestore">ดูและเตรียมย้อนคืนสำรองล่าสุด</button><button id="authorBackupDownload">ดาวน์โหลดสำรองล่าสุด</button><a href="maintenance-guide.html?v=68" target="_blank" rel="noopener">คู่มือดูแลข้อมูลโดยไม่ใช้ Codex</a></details><p id="authorStatus" role="status" aria-live="polite"></p>`;el('dbEditorTools').append(panel);
function allowed(){if(!uid||returnScreen!=='menuScreen')throw Error('เปิดเครื่องมือจากฐานข้อมูลในเมนูหลัก');}
function notice(s){el('authorStatus').textContent=s;}
function all(){return R.records(DB);}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function selected(){const row=all().find(r=>r.key===el('authorTemplate').value);if(!row)throw Error('เลือกแม่แบบก่อน');return row;}
function mechanic(){const r=selected(),player=DecideCatalogActions.compile(r),monster=DecideMonsterAI.compile(r);el('authorMechanic').textContent=(player?'กลไกผู้เล่น: '+player.description+(player.weapons.length?' • อาวุธ '+player.weapons.join(', '):'')+(player.shield?' • ต้องมีโล่':''):monster?'กลไกมอนสเตอร์: '+monster.name+' · ระยะ '+monster.range:r.kind==='weapon'?'ชนิดอาวุธ '+DecideCatalogEquipment.weapon(r).type:'ใช้ข้อมูลและกติกาของแม่แบบนี้')+' • ชื่ออ้างอิงใหม่จะคงที่ แก้ชื่อที่แสดงได้ภายหลัง';}
function refresh(){const prior=el('authorTemplate').value,kind=el('dbKind').value,rows=A.templates(all()).filter(r=>kind==='all'||r.kind===kind);el('authorTemplate').replaceChildren();for(const r of rows){const type=S.types.find(t=>t.key===r.kind)?.label||r.kind,role=['skill','spell'].includes(r.kind)?DecideMonsterAI.compile(r)?' · มอนสเตอร์':' · ผู้เล่น':'';el('authorTemplate').add(new Option(type+' · '+(r.displayName||r.name)+role,r.key));}if(rows.some(r=>r.key===prior))el('authorTemplate').value=prior;else if(rows.some(r=>r.key==='spell:preset-spell-fire'))el('authorTemplate').value='spell:preset-spell-fire';el('authorCreate').disabled=el('authorRequest').disabled=!rows.length;if(rows.length)mechanic();else el('authorMechanic').textContent='หมวดนี้ยังไม่มีแม่แบบสร้างรายการใหม่ที่รองรับ';}
function backupStore(mode,operation){return new Promise((resolve,reject)=>{const open=indexedDB.open('decide-fate-content-backup',1);open.onupgradeneeded=()=>open.result.createObjectStore('latest');open.onerror=()=>reject(Error('เปิดที่เก็บสำรองไม่ได้ โปรดส่งออกข้อมูลเต็มชุดก่อน'));open.onblocked=()=>reject(Error('ที่เก็บสำรองถูกล็อก โปรดปิดแท็บเกมอื่นแล้วลองใหม่'));open.onsuccess=()=>{const db=open.result,tx=db.transaction('latest',mode),store=tx.objectStore('latest');let result;try{const request=operation(store);request.onsuccess=()=>{result=request.result;};}catch(error){db.close();reject(error);return;}tx.oncomplete=()=>{db.close();resolve(result);};tx.onerror=()=>{db.close();reject(Error('บันทึก/อ่านสำรองไม่สำเร็จ จึงยังไม่เปลี่ยนฐานข้อมูล'));};};});}
const getBackup=account=>backupStore('readonly',s=>s.get(account)),putBackup=(account,snapshot)=>backupStore('readwrite',s=>s.put({format:'evervale-content-v1',createdAt:new Date().toISOString(),overrides:snapshot},account));
async function commit(next,fingerprint,account){allowed();const current=E.snapshot(),clean=E.validate(next);if(uid!==account||A.fingerprint(current)!==fingerprint)throw Error('ฐานข้อมูลหรือบัญชีเปลี่ยน โปรดตรวจชุดข้อมูลอีกครั้ง');await putBackup(account,current);if(uid!==account||A.fingerprint(E.snapshot())!==fingerprint)throw Error('มีข้อมูลเปลี่ยนระหว่างสำรอง โปรดตรวจชุดข้อมูลใหม่');E.commit(clean);E.renderDatabase();pending=null;el('authorReview').hidden=true;notice('บันทึกข้อมูลในเครื่องและสำรองแล้ว • รอข้อความซิงก์คลาวด์สำเร็จก่อนเปลี่ยนเครื่อง');}
function text(value){return value===undefined?'(ค่าเดิมจากแม่แบบ)':typeof value==='string'?value.length>100?value.slice(0,100)+'…':value:JSON.stringify(value);}
function review(staged,label='ชุดข้อมูลจาก AI'){pending={...staged,account:uid};el('authorChanges').replaceChildren();const heading=document.createElement('p');heading.textContent=label+' • สร้าง '+staged.created.length+' รายการ / แก้ '+staged.changed.length+' รายการ';el('authorChanges').append(heading);for(const row of staged.created){const p=document.createElement('p');p.textContent='เพิ่ม: '+row.name+' · '+row.key;el('authorChanges').append(p);}for(const row of staged.changed){const div=document.createElement('div'),title=document.createElement('strong');title.textContent=row.name+' · '+row.key;div.append(title);for(const f of row.fields){const p=document.createElement('p');p.textContent=f.field+': '+text(f.before)+' → '+text(f.after);div.append(p);}el('authorChanges').append(div);}el('authorReview').hidden=false;notice(['ตรวจผ่านแล้ว ยังไม่บันทึกจนกว่าจะกดยืนยัน',...A.reviewWarnings(staged)].join(' • '));}
async function run(fn){try{allowed();await fn();}catch(error){notice(error.message);}}
el('authorTemplate').onchange=()=>run(()=>mechanic());
el('authorCreate').onclick=()=>run(async()=>{const template=selected(),name=el('authorName').value.trim();if(!name)throw Error('กรอกชื่ออ้างอิงรายการใหม่ก่อน');const current=E.snapshot(),id='custom-'+template.kind.toLowerCase()+'-'+crypto.randomUUID(),created=A.create(template,name,id),next=copy(current),registry=copy(next[A.KEY]||{v:1,records:[]});registry.records.push(created);next[A.KEY]=registry;await commit(next,A.fingerprint(current),uid);E.open(created.kind+':'+id);});
el('authorRequest').onclick=()=>run(()=>{const template=selected(),rows=all(),request=A.request(template,E.snapshot(),S,rows,'custom-'+template.kind.toLowerCase()+'-'+crypto.randomUUID());if(el('authorName').value.trim())request.exampleResponse.create[0].name=el('authorName').value.trim();request.currentRecords=rows.filter(r=>r.kind===template.kind&&(r.templateKey||r.key===template.key)).slice(0,20).map(r=>({key:r.key,name:r.name,values:Object.fromEntries(A.fieldsFor(r,S).filter(f=>f.key!=='name').map(f=>[f.key,r[f.key]??f.default]))}));download('decide-fate-ai-request.txt','งานที่ต้องการ: '+(el('authorTask').value.trim()||'ช่วยสร้างข้อมูลใหม่จากแม่แบบนี้ ไม่แก้โค้ด')+'\n\n'+JSON.stringify(request,null,2),'text/plain;charset=utf-8');notice('คัดลอกไฟล์คำสั่งไปใช้ใน ChatGPT/Claude ได้ทีละชุด ระบบไม่ได้ส่งข้อมูลออกไปให้ AI');});
el('authorPreview').onclick=()=>run(()=>{pending=null;el('authorReview').hidden=true;const staged=A.stage(A.decode(el('authorPack').value),E.snapshot(),all());staged.next=E.validate(staged.next);review(staged);});
el('authorFile').onchange=()=>run(async()=>{const file=el('authorFile').files[0];if(!file)return;if(file.size>2000000)throw Error('ไฟล์ใหญ่เกิน 2 MB');el('authorPack').value=await file.text();el('authorFile').value='';notice('โหลดคำตอบแล้ว กดตรวจและดูสิ่งที่จะเปลี่ยน');});
el('authorApply').onclick=()=>run(async()=>{if(!pending)throw Error('ตรวจชุดข้อมูลก่อน');const staged=pending;await commit(staged.next,staged.baseFingerprint,staged.account);});
el('authorCancel').onclick=()=>{pending=null;el('authorReview').hidden=true;notice('ยกเลิกแล้ว ฐานข้อมูลไม่เปลี่ยน');};
el('authorRestore').onclick=()=>run(async()=>{const account=uid,b=await getBackup(account);if(uid!==account)throw Error('บัญชีเปลี่ยนแล้ว');if(!b)throw Error('ยังไม่มีสำรองจากเครื่องมือนี้');const current=E.snapshot(),next=E.validate(A.restore(current,b.overrides)),before=all(),after=R.records({...DB,overrides:next}),changed=[];for(const row of after){const old=before.find(r=>r.key===row.key);const fields=Object.keys(row).filter(k=>!['key','id','kind','name'].includes(k)&&JSON.stringify(row[k])!==JSON.stringify(old?.[k])).map(field=>({field,before:old?.[field],after:row[field]}));if(fields.length)changed.push({key:row.key,name:row.name,fields});}review({next,created:[],changed,baseFingerprint:A.fingerprint(current)},'ย้อนคืนสำรอง '+b.createdAt+' • รายการใหม่ที่ไม่มีในสำรองจะเก็บไว้เป็นปิดใช้งาน');});
el('authorBackupDownload').onclick=()=>run(async()=>{const b=await getBackup(uid);if(!b)throw Error('ยังไม่มีสำรองจากเครื่องมือนี้');download('decide-fate-content-backup.json',JSON.stringify(b,null,2));});
el('dbKind').addEventListener('change',refresh);window.addEventListener('evervale-content-save',refresh);window.DecideContentTools={refresh,importLibrary:next=>commit(next,A.fingerprint(E.snapshot()),uid)};refresh();
})();
